import styled from '@emotion/styled';

interface StyledPerformanceToolContentProps {
  $centered?: boolean;
}

export const StyledPerformanceToolContent = styled.div<StyledPerformanceToolContentProps>(
  ({ $centered }) => ({
    display: 'flex',
    flexDirection: 'column',
    gap: '24px',
    ...($centered && {
      width: '100%',
      justifyContent: 'center',
      alignItems: 'center',
    }),
  }),
);
